let cropState=null;
function drawCrop(){if(!cropState)return;const s=cropState,canvas=document.querySelector('#crop-canvas'),ctx=canvas.getContext('2d');s.zoom=Number(document.querySelector('#crop-zoom').value);const scale=Math.max(512/s.image.naturalWidth,512/s.image.naturalHeight)*s.zoom,w=s.image.naturalWidth*scale,h=s.image.naturalHeight*scale;s.dx=Math.max(-(w-512)/2,Math.min((w-512)/2,s.dx));s.dy=Math.max(-(h-512)/2,Math.min((h-512)/2,s.dy));ctx.clearRect(0,0,512,512);ctx.drawImage(s.image,(512-w)/2+s.dx,(512-h)/2+s.dy,w,h);}
function resetCrop(){if(!cropState)return;cropState.dx=cropState.dy=0;document.querySelector('#crop-zoom').value=1;drawCrop();}
uploadPortrait=async function(event){const file=event.target.files?.[0];event.target.value='';if(!file||!c())return;const charId=c().id,status=document.querySelector('#portrait-upload-status');status.textContent='Abrindo imagem para recorte…';try{if(!file.type.startsWith('image/')||file.size>20000000)throw Error('Escolha uma imagem de até 20 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Use uma imagem JPG, PNG ou WebP.'));i.src=data;});cropState={image,charId,name:file.name.replace(/\.[^.]+$/,'').slice(0,60)||'Meu retrato',dx:0,dy:0,zoom:1};document.querySelector('#crop-zoom').value=1;document.querySelector('#crop-message').textContent='Arraste a imagem. Use dois dedos em pinça ou a barra para ajustar o zoom.';drawCrop();document.querySelector('#crop-dialog').showModal();status.textContent='A imagem só será salva depois de confirmar o recorte.';}catch(e){status.textContent=e.message||'Não foi possível abrir a imagem.';}};
async function confirmCrop(){if(!cropState)return;const button=document.querySelector('#crop-confirm');button.disabled=true;try{drawCrop();const out=document.createElement('canvas');out.width=out.height=384;out.getContext('2d').drawImage(document.querySelector('#crop-canvas'),0,0,384,384);const p={id:crypto.randomUUID(),name:cropState.name,data:out.toDataURL('image/jpeg',.88)};if(!isPortraitData(p.data))throw Error('Não foi possível salvar o recorte.');await storePortrait(p);uploadedPortraits.push(p);const x=db.chars.find(x=>x.id===cropState.charId);if(x)x.portraitUpload={...p};save();cropState=null;document.querySelector('#crop-dialog').close();render();renderGallery();document.querySelector('#portrait-upload-status').textContent='Recorte salvo e aplicado ao personagem.';}catch(e){document.querySelector('#crop-message').textContent=e.message||'Não foi possível salvar.';}finally{button.disabled=false;}}
const cropCanvas=document.querySelector('#crop-canvas');let dragCrop=null;const cropPointers=new Map();let pinchCrop=null;
function cropPoint45(p){const rect=cropCanvas.getBoundingClientRect();return {x:(p.x-rect.left)*512/rect.width,y:(p.y-rect.top)*512/rect.height};}
function beginPinch45(){const [a,b]=[...cropPointers.values()];if(!a||!b||!cropState)return;const pa=cropPoint45(a),pb=cropPoint45(b);pinchCrop={distance:Math.max(1,Math.hypot(pa.x-pb.x,pa.y-pb.y)),zoom:Number(document.querySelector('#crop-zoom').value),dx:cropState.dx,dy:cropState.dy,x:(pa.x+pb.x)/2,y:(pa.y+pb.y)/2};dragCrop=null;}
cropCanvas.addEventListener('pointerdown',e=>{if(!cropState)return;e.preventDefault();cropPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});cropCanvas.setPointerCapture(e.pointerId);if(cropPointers.size===2)beginPinch45();else if(cropPointers.size===1)dragCrop={x:e.clientX,y:e.clientY};});
cropCanvas.addEventListener('pointermove',e=>{if(!cropState||!cropPointers.has(e.pointerId))return;e.preventDefault();cropPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(cropPointers.size>=2){if(!pinchCrop)beginPinch45();const [a,b]=[...cropPointers.values()],pa=cropPoint45(a),pb=cropPoint45(b),distance=Math.hypot(pa.x-pb.x,pa.y-pb.y),zoom=Math.max(1,Math.min(4,pinchCrop.zoom*distance/pinchCrop.distance)),ratio=zoom/pinchCrop.zoom;cropState.dx=(pa.x+pb.x)/2-256-(pinchCrop.x-256-pinchCrop.dx)*ratio;cropState.dy=(pa.y+pb.y)/2-256-(pinchCrop.y-256-pinchCrop.dy)*ratio;document.querySelector('#crop-zoom').value=zoom;drawCrop();}else if(dragCrop){const ratio=512/cropCanvas.getBoundingClientRect().width;cropState.dx+=(e.clientX-dragCrop.x)*ratio;cropState.dy+=(e.clientY-dragCrop.y)*ratio;dragCrop={x:e.clientX,y:e.clientY};drawCrop();}});
for(const name of ['pointerup','pointercancel','lostpointercapture'])cropCanvas.addEventListener(name,e=>{cropPointers.delete(e.pointerId);pinchCrop=null;const remaining=[...cropPointers.values()][0];dragCrop=remaining?{...remaining}:null;});
document.querySelector('#crop-dialog').addEventListener('close',()=>{cropState=null;dragCrop=null;pinchCrop=null;cropPointers.clear();});
